CREATE TABLE IF NOT EXISTS accounts (   id            INTEGER PRIMARY KEY AUTOINCREMENT,   email         TEXT NOT NULL UNIQUE,   role          TEXT NOT NULL,   status        TEXT NOT NULL DEFAULT 'pending',   created_at    TEXT NOT NULL DEFAULT (datetime('now')),   CHECK (role IN ('developer','partner')),   CHECK (status IN ('pending','verified','rejected','suspended')) );
CREATE TABLE IF NOT EXISTS contact_views (   id            INTEGER PRIMARY KEY AUTOINCREMENT,   viewer_id     INTEGER NOT NULL,   target_type   TEXT NOT NULL,   target_id     INTEGER NOT NULL,   ym            TEXT NOT NULL,   viewed_at     TEXT NOT NULL DEFAULT (datetime('now')),   CHECK (target_type IN ('developer','partner')),   FOREIGN KEY (viewer_id) REFERENCES accounts(id) ON DELETE CASCADE,   UNIQUE (viewer_id, target_type, target_id) );
CREATE TABLE IF NOT EXISTS developer_profiles (   account_id    INTEGER PRIMARY KEY,   studio_name   TEXT,   contact_email TEXT,   proof_type    TEXT,   proof_image   TEXT,   review_note   TEXT,   updated_at    TEXT NOT NULL DEFAULT (datetime('now')), intro TEXT, logo TEXT,   FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE CASCADE );
CREATE TABLE IF NOT EXISTS favorites (   id INTEGER PRIMARY KEY AUTOINCREMENT,   account_id INTEGER NOT NULL,   game_id INTEGER NOT NULL,   created_at TEXT DEFAULT (datetime('now')) );
CREATE TABLE IF NOT EXISTS game_claims (   id            INTEGER PRIMARY KEY AUTOINCREMENT,   account_id    INTEGER NOT NULL,   game_id       INTEGER NOT NULL,   status        TEXT NOT NULL DEFAULT 'pending',   proof_image   TEXT,   created_at    TEXT NOT NULL DEFAULT (datetime('now')),   CHECK (status IN ('pending','approved','rejected')),   FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE CASCADE,   FOREIGN KEY (game_id)    REFERENCES games(id)    ON DELETE CASCADE,   UNIQUE (account_id, game_id) );
CREATE TABLE IF NOT EXISTS games (   id            INTEGER PRIMARY KEY AUTOINCREMENT,   slug          TEXT UNIQUE,   t_en          TEXT, t_zh TEXT, t_ko TEXT,   d_en          TEXT, d_zh TEXT, d_ko TEXT,   full_en       TEXT, full_zh TEXT, full_ko TEXT,   studio_en     TEXT, studio_zh TEXT, studio_ko TEXT,   developer     TEXT,   stage         TEXT,   genres        TEXT,   needs         TEXT,   platforms     TEXT,   region        TEXT,   cover         TEXT,   screenshots   TEXT,   studio_logo   TEXT,   video         TEXT,   claimed_by    INTEGER,   visible       INTEGER NOT NULL DEFAULT 1,   sort          INTEGER NOT NULL DEFAULT 0,   created_at    TEXT NOT NULL DEFAULT (datetime('now')), status TEXT DEFAULT 'approved', review_note TEXT, steam_url TEXT, feishu_id TEXT, contact TEXT, featured INTEGER DEFAULT 0, feature_state TEXT DEFAULT 'none', feature_note TEXT, demo_url TEXT, demo_note TEXT, deep_coop INTEGER DEFAULT 0,   FOREIGN KEY (claimed_by) REFERENCES accounts(id) ON DELETE SET NULL );
CREATE TABLE IF NOT EXISTS login_codes (   id            INTEGER PRIMARY KEY AUTOINCREMENT,   email         TEXT NOT NULL,   code          TEXT NOT NULL,   expires_at    TEXT NOT NULL,   used          INTEGER NOT NULL DEFAULT 0,   created_at    TEXT NOT NULL DEFAULT (datetime('now')) );
CREATE TABLE IF NOT EXISTS partner_profiles (   account_id    INTEGER PRIMARY KEY,   name_zh       TEXT,   name_en       TEXT,   logo          TEXT,   kinds         TEXT,   region        TEXT,   intro         TEXT,   genres        TEXT,   markets       TEXT,   steam_url     TEXT,   website       TEXT,   contact_email TEXT,   proof_type    TEXT,   proof_image   TEXT,   review_note   TEXT,   sort          INTEGER NOT NULL DEFAULT 0,   updated_at    TEXT NOT NULL DEFAULT (datetime('now')), name_ko TEXT, verified_email TEXT, intro_en TEXT, intro_zh TEXT, intro_ko TEXT, contact_public INTEGER DEFAULT 1, pref_genres TEXT, pref_regions TEXT, pref_budget TEXT, pref_notes TEXT, pref_updated_at TEXT,   FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE CASCADE );
CREATE TABLE IF NOT EXISTS partner_works (   id            INTEGER PRIMARY KEY AUTOINCREMENT,   partner_id    INTEGER NOT NULL,   title         TEXT NOT NULL,   steam_url     TEXT NOT NULL,   cover         TEXT,   work_type     TEXT,   sort          INTEGER NOT NULL DEFAULT 0,   FOREIGN KEY (partner_id) REFERENCES partner_profiles(account_id) ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS idx_accounts_email ON accounts(email);
CREATE INDEX IF NOT EXISTS idx_claims_status ON game_claims(status);
CREATE INDEX IF NOT EXISTS idx_codes_email ON login_codes(email, used);
CREATE UNIQUE INDEX IF NOT EXISTS idx_fav_unique ON favorites(account_id, game_id);
CREATE INDEX IF NOT EXISTS idx_games_claimed ON games(claimed_by);
CREATE UNIQUE INDEX IF NOT EXISTS idx_games_feishu ON games(feishu_id);
CREATE INDEX IF NOT EXISTS idx_games_sort ON games(sort);
CREATE INDEX IF NOT EXISTS idx_partner_sort ON partner_profiles(sort);
CREATE INDEX IF NOT EXISTS idx_views_viewer_ym ON contact_views(viewer_id, ym);
CREATE INDEX IF NOT EXISTS idx_works_partner ON partner_works(partner_id, sort);
